import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(): AIProvider {
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: 'ok'};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

describe('beforeSession throwing', () => {
  it('runs onError and afterSession hooks even when beforeSession throws', async () => {
    const errorToThrow = new Error('thrown in beforeSession');
    const callOrder: string[] = [];

    const orchestrator = createChatOrchestrator(createMockProvider(), promptBuilder, undefined, {
      hooks: {
        beforeSession: async () => {
          callOrder.push('beforeSession');
          throw errorToThrow;
        },
        onError: async () => {
          callOrder.push('onError');
        },
        afterSession: async () => {
          callOrder.push('afterSession');
        },
      },
    });

    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('thrown in beforeSession');

    expect(callOrder).toEqual(['beforeSession', 'onError', 'afterSession']);
  });
});

